/*
 * Zaidan typeset — a port of shadcn/typeset.
 * https://ui.shadcn.com/docs/typeset
 *
 * A styling system for HTML and rendered markdown. Everything inside a
 * `typeset` container is styled; everything outside is untouched. Three
 * variables carry the rhythm: `--typeset-size`, `--typeset-leading`, and
 * `--typeset-flow`.
 *
 * Append-stability contract: this file must never use forward-looking
 * selectors (`:last-child`, `:has()`, `:empty`, …) and must only ever space
 * forward (`margin-block-end` is always 0). That is what lets streamed content
 * append without restyling the blocks already on screen. Enforced by
 * `src/lib/typeset.test.ts`.
 *
 * Opt an embedded component out with `not-typeset` or `data-not-typeset`.
 */

@layer components {
  .typeset {
    --typeset-font-body: inherit;
    --typeset-font-heading: var(--font-heading);
    --typeset-font-mono: var(--font-mono);
    --typeset-size: 1em;
    --typeset-leading: 1.75;
    --typeset-flow: 1.25em;
  }
}

@layer components {
  .typeset {
    margin-trim: block-start;
    overflow-wrap: break-word;
    color: var(--color-foreground, currentColor);
    font-family: var(--typeset-font-body);
    font-size: calc(var(--typeset-size) * 1.125);
    line-height: var(--typeset-leading);

    @media (min-width: 48rem), print {
      font-size: var(--typeset-size);
    }

    --typeset-muted: var(
      --color-muted-foreground,
      color-mix(in oklab, currentColor 60%, transparent)
    );
    --typeset-rule: var(--color-border, color-mix(in oklab, currentColor 20%, transparent));
  }

  .typeset *:not(:where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)) {
    /* Paragraphs. */
    &:where(p) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }

    /* Headings. */
    &:where(h1, h2, h3, h4, h5, h6) {
      margin-block-end: 0;
      color: var(--color-foreground, currentColor);
      font-family: var(--typeset-font-heading);
      font-weight: 600;
    }

    &:where(h1) {
      margin-block-start: var(--typeset-flow);
      font-size: 1.75em;
      line-height: 1.3;
    }

    &:where(h2) {
      margin-block-start: calc(var(--typeset-flow) * 1.4);
      font-size: 1.25em;
      line-height: 1.4;
    }

    &:where(h3) {
      margin-block-start: var(--typeset-flow);
      font-size: 1.125em;
      line-height: 1.45;
    }

    &:where(h4) {
      margin-block-start: var(--typeset-flow);
      font-size: 1em;
      line-height: 1.5;
    }

    &:where(h5) {
      margin-block-start: calc(var(--typeset-flow) / 0.875);
      color: var(--typeset-muted);
      font-size: 0.875em;
      font-weight: 500;
      line-height: 1.5;
    }

    &:where(h6) {
      margin-block-start: calc(var(--typeset-flow) / 0.8125);
      color: var(--typeset-muted);
      font-size: 0.8125em;
      font-weight: 500;
      line-height: 1.5;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    /* Anchors. */
    &:where([id]) {
      scroll-margin-block-start: var(--typeset-flow);
    }

    /* Headings own the space below them. */
    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: 1em;
    }

    &:where(:is(h1, h2, h3, h4) :is(code)) {
      font-size: 0.9em;
    }

    /* Links. */
    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
      text-decoration-line: underline;
    }

    &:where(a:hover) {
      text-decoration-color: currentColor;
    }

    &:where(a:focus-visible) {
      border-radius: 0.125em;
      outline: 2px solid var(--color-ring, currentColor);
      outline-offset: 2px;
    }

    &:where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
      font-weight: inherit;
    }

    /* Inline semantics. */
    &:where(strong, b) {
      font-weight: 600;
    }

    &:where(:is(h1, h2, h3, h4) :is(strong, b)) {
      font-weight: 600;
    }

    &:where(mark) {
      border-radius: 0.2em;
      background-color: color-mix(in oklab, oklch(0.86 0.17 95) 40%, transparent);
      padding: 0.05em 0.15em;
      color: inherit;
    }

    &:where(abbr[title]) {
      cursor: help;
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
    }

    &:where(del, s) {
      color: var(--typeset-muted);
      text-decoration-line: line-through;
    }

    &:where(sup, sub) {
      position: relative;
      font-size: 0.75em;
      line-height: 0;
      vertical-align: baseline;
    }

    &:where(sup) {
      top: -0.5em;
    }

    &:where(sub) {
      bottom: -0.25em;
    }

    &:where(sup a) {
      font-weight: 500;
      text-decoration-line: none;
    }

    /* Lists. */
    &:where(ul) {
      list-style-type: disc;
    }

    &:where(ol) {
      list-style-type: decimal;
    }

    &:where(ul ul) {
      list-style-type: circle;
    }

    &:where(ul ul ul) {
      list-style-type: square;
    }

    &:where(ol[type="a" i]) {
      list-style-type: lower-alpha;
    }

    &:where(ol[type="i" i]) {
      list-style-type: lower-roman;
    }

    &:where(ol[type="A" s]) {
      list-style-type: upper-alpha;
    }

    &:where(ol[type="I" s]) {
      list-style-type: upper-roman;
    }

    &:where(ul, ol) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      padding-inline-start: 1.5em;
    }

    &:where(li) {
      margin-block-start: 0.5em;
      padding-inline-start: 0.4em;
    }

    &:where(li > p, li > ul, li > ol) {
      margin-block-start: 0.5em;
    }

    &:where(ul > li)::marker {
      color: var(--typeset-muted);
    }

    &:where(ol > li)::marker {
      color: var(--typeset-muted);
    }

    /* GFM task lists. */
    &:where(ul.contains-task-list) {
      padding-inline-start: 0.25em;
      list-style-type: none;
    }

    &:where(li.task-list-item > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      accent-color: var(--color-primary, currentColor);
      vertical-align: -0.1em;
    }

    /* Disclosures. */
    &:where(details) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }

    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }

    &:where(summary)::marker {
      color: var(--typeset-muted);
    }

    /* Keyboard keys. */
    &:where(kbd) {
      border: 1px solid var(--typeset-rule);
      border-block-end-width: 2px;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.0625em 0.35em;
      font-family: inherit;
      font-size: 0.85em;
      font-weight: 500;
    }

    /* Definition lists. */
    &:where(dl) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }

    &:where(dt) {
      margin-block-start: 1em;
      font-weight: 500;
    }

    &:where(dt + dt) {
      margin-block-start: 0.25em;
    }

    &:where(dd) {
      margin-block-start: 0.25em;
      margin-inline-start: 0;
      padding-inline-start: 1em;
      color: var(--typeset-muted);
    }

    /* Inline code. */
    &:where(:not(pre) > code) {
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      background-color: var(--color-muted, color-mix(in oklab, currentColor 8%, transparent));
      padding: 0.125em 0.3em;
      font-family: var(--typeset-font-mono);
      font-size: 0.85em;
    }

    /* Code blocks. */
    &:where(pre) {
      direction: ltr;
      margin-block-start: calc(var(--typeset-flow) / 0.875);
      margin-block-end: 0;
      border-radius: var(--radius, 0.5em);
      background-color: var(--color-muted, color-mix(in oklab, currentColor 8%, transparent));
      padding: 0.75em 1em;
      overflow-x: auto;
      font-family: var(--typeset-font-mono);
      font-size: 0.875em;
      line-height: 1.5;
      tab-size: 2;
    }

    &:where(pre code) {
      border-radius: 0;
      background-color: transparent;
      padding: 0;
      font-family: inherit;
      font-size: inherit;
    }

    /* Blockquote. */
    &:where(blockquote) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
      border-inline-start: 2px solid var(--typeset-rule);
      padding-inline-start: 1em;
    }

    /* Dividers. */
    &:where(hr) {
      margin-block-start: calc(var(--typeset-flow) * 2.4);
      margin-block-end: 0;
      border: 0;
      border-block-start: 1px solid var(--typeset-rule);
    }

    &:where(hr + h1, hr + h2, hr + h3, hr + h4) {
      margin-block-start: var(--typeset-flow);
    }

    /* GFM footnotes. */
    &:where(.footnotes, [data-footnotes]) {
      margin-block-start: calc(var(--typeset-flow) * 2);
      border-block-start: 1px solid var(--typeset-rule);
      padding-block-start: var(--typeset-flow);
      color: var(--typeset-muted);
      font-size: 0.875em;
    }

    /* Math. */
    &:where(math[display="block"]) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      padding-block: 0.25em;
      overflow-x: auto;
      overflow-y: hidden;
    }

    /* Media. */
    &:where(img, video) {
      max-width: 100%;
      height: auto;
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      border-radius: var(--radius, 0.5em);
    }

    &:where(p img) {
      margin-block-start: 0;
    }

    &:where(figure) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }

    &:where(figcaption, caption) {
      margin-block-start: calc(0.75em / 0.875);
      color: var(--typeset-muted);
      font-size: 0.875em;
      text-align: center;
    }

    &:where(caption) {
      caption-side: bottom;
    }

    /* Tables. Separators sit on cells, not tr:last-child: append-safe.
       Bare tables stay real tables (keep their semantics) and wrap to fit. */
    &:where(table) {
      max-width: 100%;
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      border-spacing: 0;
      border-collapse: separate;
      border-block-end: 1px solid var(--typeset-rule);
      font-size: 1em;
      font-variant-numeric: tabular-nums;
      line-height: 1.5;
    }

    /* Horizontal scroll for any wide block. Wrap it and the wrapper owns the
       flow margin. Tables shrink to fit, so widen the table to make it scroll
       instead of compress. */
    &:where(.typeset-scroll) {
      margin-block-start: var(--typeset-flow);
      overflow-x: auto;
    }

    &:where(.typeset-scroll > *) {
      margin-block-start: 0;
    }

    &:where(.typeset-scroll table) {
      width: max-content;
      max-width: none;
    }

    &:where(thead th) {
      padding: 0.65em 1em;
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
    }

    &:where(:is(tbody, tfoot) :is(td, th)) {
      border-block-start: 1px solid var(--typeset-rule);
      padding: 0.75em 1em;
      text-align: start;
      vertical-align: top;
    }

    &:where(tbody th, tfoot th) {
      font-weight: 500;
    }

    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }

    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }

    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }

    /* Blocks inside list items keep the list's tighter rhythm. */
    &:where(li > blockquote, li > table, li > figure) {
      margin-block-start: 0.5em;
    }

    &:where(li > pre) {
      margin-block-start: calc(0.5em / 0.875);
    }

    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }

      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }

    /* Forced colors strips the code background, so give it a border. */
    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  /* First child adds no space above. Last so it wins ties. */
  .typeset
  > :where(:first-child):not(
    :where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)
  ),
  .typeset
    > :where(:first-child)
    > :where(:first-child):not(
      :where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)
    ),
  .typeset
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child,
      figure > picture > img
    ):not(:where(.not-typeset, [data-not-typeset], .not-typeset *, [data-not-typeset] *)) {
    margin-block-start: 0;
  }
}
